mapper.select:
/* 문의사항 목록 조회 inq.selectInqList */ SELECT A.INQ_ID , A.TITLE , A.CAT_CD , C.CODE_NM AS CAT_NM , A.AGENT_ID , G.AGENT_NM , A.STATUS_CD , S.CODE_NM AS STATUS_NM , A.SECRET_YN , A.CRTR_ID , U.USER_NM AS CRTR_NM , DATE_FORMAT(A.CREATE_DT, '%Y-%m-%d %H:%i:%s') AS CREATE_DT , IF(EXISTS (SELECT 1 FROM TB_INQ_ANSR R WHERE R.INQ_ID = A.INQ_ID AND R.DEPTH = 1 AND R.USE_YN = 'Y'), 'Y', 'N') AS ANSWER_YN FROM TB_INQ A LEFT JOIN TB_CODE C ON C.CODE_GRP_ID = 'IS000002' AND C.CODE_ID = A.CAT_CD LEFT JOIN TB_CODE S ON S.CODE_GRP_ID = 'IS000001' AND S.CODE_ID = A.STATUS_CD LEFT JOIN TB_AGT G ON G.AGENT_ID = A.AGENT_ID LEFT JOIN TB_USER U ON U.USER_ID = A.CRTR_ID WHERE A.USE_YN = 'Y'
AND A.CAT_CD = #{catCd}
AND A.STATUS_CD = #{statusCd}
AND (#{manageYn} = 'Y' OR A.SECRET_YN = 'N' OR A.CRTR_ID = #{userId}) AND ( A.TITLE LIKE CONCAT('%', #{searchKeyword}, '%') OR A.CONTENT LIKE CONCAT('%', #{searchKeyword}, '%') OR U.USER_NM LIKE CONCAT('%', #{searchKeyword}, '%') )
ORDER BY A.CREATE_DT DESC, A.INQ_ID DESC LIMIT #{firstIndex}, #{recordCountPerPage}

/* 문의사항 목록 건수 조회 inq.selectInqListCnt */ SELECT COUNT(1) FROM TB_INQ A LEFT JOIN TB_USER U ON U.USER_ID = A.CRTR_ID WHERE A.USE_YN = 'Y'
AND A.CAT_CD = #{catCd}
AND A.STATUS_CD = #{statusCd}
AND (#{manageYn} = 'Y' OR A.SECRET_YN = 'N' OR A.CRTR_ID = #{userId}) AND ( A.TITLE LIKE CONCAT('%', #{searchKeyword}, '%') OR A.CONTENT LIKE CONCAT('%', #{searchKeyword}, '%') OR U.USER_NM LIKE CONCAT('%', #{searchKeyword}, '%') )

mapper.insert:
/* 문의사항 등록 inq.insertInq */
INSERT INTO TB_INQ (
    INQ_ID
    , TITLE
    , CONTENT
    , CAT_CD
    , AGENT_ID
    , STATUS_CD
    , SECRET_YN
    , USE_YN
    , CRTR_ID
    , CREATE_DT
    , MODIFY_DT
) VALUES (
    #{inqId}
    , #{title}
    , #{content}
    , #{catCd}
    , #{agentId, jdbcType=VARCHAR}
    , #{statusCd}
    , #{secretYn}
    , 'Y'
    , #{crtrId}
    , NOW()
    , NOW()
)

mapper.update:
/* 문의사항 수정 inq.updateInq */
UPDATE TB_INQ
SET
    TITLE = #{title}
    , CONTENT = #{content}
    , CAT_CD = #{catCd}
    , AGENT_ID = #{agentId, jdbcType=VARCHAR}
    , SECRET_YN = #{secretYn}
    , MODIFY_DT = NOW()
WHERE INQ_ID = #{inqId}
    AND USE_YN = 'Y'

/* 문의사항 처리상태 변경 inq.updateInqStatus */
UPDATE TB_INQ
SET
    STATUS_CD = #{statusCd}
    , MODIFY_DT = NOW()
WHERE INQ_ID = #{inqId}
    AND USE_YN = 'Y'

