/* 문의 답변·댓글 등록 inq.insertInqAnsr */
INSERT INTO TB_INQ_ANSR (
    ANSR_ID
    , INQ_ID
    , UP_ANSR_ID
    , CONTENT
    , ANSR_USER_ID
    , DEPTH
    , SORT_ORD
    , USE_YN
    , CREATE_DT
    , MODIFY_DT
) VALUES (
    #{ansrId}
    , #{inqId}
    , #{upAnsrId, jdbcType=VARCHAR}
    , #{content}
    , #{ansrUserId}
    , #{depth}
    , #{sortOrd}
    , 'Y'
    , NOW()
    , NOW()
)

mapper.update:
/* 문의 답변·댓글 수정 inq.updateInqAnsr */
UPDATE TB_INQ_ANSR
SET
    CONTENT = #{content}
    , MODIFY_DT = NOW()
WHERE ANSR_ID = #{ansrId}
    AND USE_YN = 'Y'

mapper.insert:
/* 문의 첨부파일 등록 inq.insertInqFile */
INSERT INTO TB_INQ_FILE (
    INQ_FILE_ID
    , INQ_ID
    , FILE_PATH
    , FILE_NM
    , FILE_SIZE
    , FILE_TYPE
    , CREATE_DT
    , MODIFY_DT
    , CREATE_ID
    , MODIFY_ID
) VALUES (
    #{inqFileId}
    , #{inqId}
    , #{filePath}
    , #{fileNm}
    , #{fileSize}
    , #{fileType, jdbcType=VARCHAR}
    , NOW()
    , NOW()
    , #{createId}
    , #{createId}
)

mapper.delete:
/* 문의 첨부파일 삭제 inq.deleteInqFile */
DELETE FROM TB_INQ_FILE
WHERE INQ_FILE_ID = #{inqFileId}

mapper.select:
/* 공통코드명 조회 inq.selectInqCodeNm */
SELECT
    CODE_NM
FROM TB_CODE
WHERE CODE_GRP_ID = #{codeGrpId}
    AND CODE_ID = #{codeId}
    AND USE_YN = 'Y'

/* 사용 중인 에이전트 건수 조회 inq.selectInqAgentCnt */
SELECT
    COUNT(1)
FROM TB_AGT
WHERE AGENT_ID = #{agentId}
    AND USE_YN = 'Y'
